for slug,title,category,source,alt,related,intro,sections,scenario,questions in MORE:
    ARTICLES.append({"slug":slug,"title":title,"category":category,"source":source,"excerpt":intro.split(". ")[0]+".","alt":alt,"related":related,"intro":intro,"sections":sections,"scenario":scenario,"questions":questions,
    "faq":[["What should a provider demonstrate before live work?","Ask for a representative, privacy-safe walkthrough that shows source use, permissions, exception handling, and a reproducible handoff."],["Can the scope expand after the pilot?","Yes. Expand only the parts supported by reviewed evidence, updated access, clear ownership, and an explicit acceptance record."],["Who retains judgment outside the administrative lane?","The business should name the qualified or authorized owner rather than leaving the assistant to infer authority from urgency."]]})

def render(a):
    body=[f"# {a['title']}","",f"Published {PUBDATE}.","",a["intro"]]
    for index,(heading,text) in enumerate(a["sections"]):
        shown = f"{a['title']}: {heading}" if index == 0 else heading
        body += ["",f"## {shown}","",text]
    body += ["","## A realistic boundary test","",a["scenario"],"","## Questions to put in the provider scorecard",""]
    for i,q in enumerate(a["questions"],1):
        body += [f"### {i}. {q}","",f"Require an answer tied to this {a['alt']} workflow: name the controlling record, the person with decision authority, the action the assistant may take, the condition that stops work, and the evidence retained. Test the answer with one normal case and one exception. Ask who notices a failed handoff, how it is corrected, and when the buyer is informed. A sales assurance without an inspectable example remains an assumption for the pilot, not a proven capability.",""]
    body += ["## Make the buying decision","",f"Compare providers against the actual {a['alt']} lane, not a broad list of software logos. Record exclusions, access, coverage, review effort, correction ownership, transition help, and the evidence required for acceptance. The [service library](/services) helps define adjacent roles, and the [provider comparison guide](/compare) supports a consistent selection process. The [{a['source'].upper()} resource]({SOURCES[a['source']]}) supplies current general context; apply qualified advice and the rules governing your organization. Start with a paid, bounded pilot and keep final policy, risk, contractual, professional, and exception decisions with the named business owner.","","## Frequently asked questions"]
    for q,ans in a["faq"]: body += ["",f"### {q}","",ans]
    front=f"---\nslug: {a['slug']}\ntitle: {a['title']}\nexcerpt: {a['excerpt']}\npublishedAt: {PUBDATE}\nupdatedAt: {PUBDATE}\ncategory: {a['category']}\ntags: [virtual assistant, service evaluation, workflow design]\nfeaturedImage: {IMAGE}\nheroImageAlt: {a['alt']}\nreadingTime: 10 minutes\nrelatedArticles: [{', '.join(a['related'])}]\n---\n"
    return front+"\n".join(body)+"\n"

entries=[]
for a in ARTICLES:
    p=ROOT/"content/blog"/(a["slug"]+".mdx"); text=render(a); p.write_text(text)
    words=len(re.findall(r"\b[\w’-]+\b",text.split("---",2)[-1]))
    if words<900: raise SystemExit(f"{a['slug']}: {words} words")
    entries.append({"family":"blog","topic":a["title"],"slug":a["slug"],"sources":[SOURCES[a["source"]]],"contentHash":hashlib.sha256(p.read_bytes()).hexdigest(),"actualPublicationDate":PUBDATE,"commitSha":"PENDING_COMBINED_COMMIT","deploymentEvidence":"PENDING_BROWSER_OPERATOR_EXACT_SHA_SUCCESS","liveUrl":f"https://bestvirtualassistantservices.com/blog/{a['slug']}","verificationTime":"PENDING_LIVE_VERIFICATION","sourcePath":str(p.relative_to(ROOT)),"imagePath":IMAGE,"bodyWords":words})

